          "title": "First-Principles NumPy/SciPy: Bukti Monte Carlo KS-Test 100% False Alarm di N=50.000 vs Stabilitas W1, PSI & MMD^2",
          "language": "python",
          "filename": "36_1_ks_false_alarm_vs_w1_psi_mmd_scratch.py",
          "code": "import numpy as np\nfrom scipy.stats import ks_2samp, wasserstein_distance\n\ndef ks_fast_2samp(u: np.ndarray, v: np.ndarray) -> tuple[float, float]:\n    \"\"\"Fast vectorized two-sample KS statistic D and asymptotic Kolmogorov p-value.\"\"\"\n    u_s = np.sort(np.asarray(u, dtype=float))\n    v_s = np.sort(np.asarray(v, dtype=float))\n    all_x = np.sort(np.concatenate([u_s, v_s]))\n    cdf_u = np.searchsorted(u_s, all_x, side=\"right\") / len(u_s)\n    cdf_v = np.searchsorted(v_s, all_x, side=\"right\") / len(v_s)\n    D = float(np.max(np.abs(cdf_u - cdf_v)))\n    n_eff = len(u_s) * len(v_s) / (len(u_s) + len(v_s))\n    p_asymp = float(min(1.0, 2.0 * np.exp(-2.0 * n_eff * D * D)))\n    return D, p_asymp\n\ndef wasserstein_1d_scratch(u: np.ndarray, v: np.ndarray) -> float:\n    \"\"\"Exact 1D Wasserstein-1 (Earth Mover's Distance) via sorted empirical CDFs.\"\"\"\n    u_s = np.sort(np.asarray(u, dtype=float))\n    v_s = np.sort(np.asarray(v, dtype=float))\n    if len(u_s) == len(v_s):\n        return float(np.mean(np.abs(u_s - v_s)))\n    all_x = np.sort(np.concatenate([u_s, v_s]))\n    deltas = np.diff(all_x)\n    cdf_u = np.searchsorted(u_s, all_x[:-1], side=\"right\") / len(u_s)\n    cdf_v = np.searchsorted(v_s, all_x[:-1], side=\"right\") / len(v_s)\n    return float(np.sum(np.abs(cdf_u - cdf_v) * deltas))\n\ndef psi_quantile_scratch(ref: np.ndarray, prod: np.ndarray, n_bins: int = 10, eps: float = 1e-6) -> float:\n    \"\"\"Population Stability Index (PSI) on reference decile edges with epsilon smoothing.\"\"\"\n    edges = np.quantile(ref, np.linspace(0.0, 1.0, n_bins + 1))\n    edges[0], edges[-1] = -np.inf, np.inf\n    p = np.clip(np.histogram(ref, bins=edges)[0] / len(ref), eps, None)\n    q = np.clip(np.histogram(prod, bins=edges)[0] / len(prod), eps, None)\n    p /= p.sum()\n    q /= q.sum()\n    return float(np.sum((q - p) * np.log(q / p)))\n\ndef rbf_mmd2_unbiased(X: np.ndarray, Y: np.ndarray, sigma: float | None = None) -> float:\n    \"\"\"Unbiased U-statistic Kernel MMD^2 (Gretton et al. 2012) with median heuristic.\"\"\"\n    X = np.atleast_2d(np.asarray(X, dtype=float))\n    Y = np.atleast_2d(np.asarray(Y, dtype=float))\n    Z = np.vstack([X, Y])\n    sq_z = np.sum((Z[:, None, :] - Z[None, :, :]) ** 2, axis=2)\n    if sigma is None:\n        tri = sq_z[np.triu_indices(len(Z), k=1)]\n        sigma = float(np.sqrt(max(np.median(tri), 1e-8)))\n    gamma = 1.0 / (2.0 * sigma * sigma)\n    n, m = len(X), len(Y)\n    Kxx = np.exp(-gamma * np.sum((X[:, None, :] - X[None, :, :]) ** 2, axis=2))\n    Kyy = np.exp(-gamma * np.sum((Y[:, None, :] - Y[None, :, :]) ** 2, axis=2))\n    Kxy = np.exp(-gamma * np.sum((X[:, None, :] - Y[None, :, :]) ** 2, axis=2))\n    term_x = (np.sum(Kxx) - np.trace(Kxx)) / (n * (n - 1))\n    term_y = (np.sum(Kyy) - np.trace(Kyy)) / (m * (m - 1))\n    return float(term_x + term_y - 2.0 * np.mean(Kxy))\n\n# 1. Eksperimen Monte Carlo (15 trial): Pergeseran mikro tak bermakna Delta_mu = 0.05 sigma\nprint(\"=== BUKTI MONTE CARLO: PERGESERAN MIKRO Delta_mu = 0.05 (15 Trial) ===\")\nfor N in [500, 5_000, 50_000]:\n    rng = np.random.default_rng(42 + N)\n    ks_alerts = 0\n    ks_ps, w1_vals, psi_vals = [], [], []\n    for _ in range(15):\n        ref_x = rng.normal(0.0, 1.0, size=N)\n        prod_x = rng.normal(0.05, 1.0, size=N)\n        _, p_val = ks_fast_2samp(ref_x, prod_x)\n        if p_val < 0.01:\n            ks_alerts += 1\n        ks_ps.append(p_val)\n        w1_vals.append(wasserstein_1d_scratch(ref_x, prod_x))\n        psi_vals.append(psi_quantile_scratch(ref_x, prod_x))\n    w1_scipy = wasserstein_distance(ref_x, prod_x)\n    ks_scipy = ks_2samp(ref_x, prod_x)\n    print(\n        f\"  N={N:6d} | KS False-Alert(p<0.01)={100*ks_alerts/15:5.1f}% \"\n        f\"| Med p={np.median(ks_ps):.2e} (SciPy={ks_scipy.pvalue:.2e}) \"\n        f\"| Mean W1={np.mean(w1_vals):.4f} (diff={abs(w1_vals[-1]-w1_scipy):.1e}) | Mean PSI={np.mean(psi_vals):.4f}\"\n    )\n\n# 2. Perbandingan 3 rezim drift (N=50.000): Mikro (0.05), Moderat (0.40), Berat (0.90 + var 1.5x)\nrng = np.random.default_rng(42)\nref_big = rng.normal(0.0, 1.0, size=50_000)\nregimes = [\n    (\"Mikro (mu+0.05, sd=1.0)\", rng.normal(0.05, 1.0, size=50_000)),\n    (\"Moderat (mu+0.40, sd=1.1)\", rng.normal(0.40, 1.1, size=50_000)),\n    (\"Berat (mu+0.90, sd=1.5)\", rng.normal(0.90, 1.5, size=50_000)),\n]\nprint(\"\\n=== PERBANDINGAN METRIK PADA N=50.000 (SUBSAMPLE m=250 UNTUK MMD^2) ===\")\nfor name, prod_big in regimes:\n    ks_stat, ks_p = ks_fast_2samp(ref_big, prod_big)\n    w1 = wasserstein_1d_scratch(ref_big, prod_big)\n    psi = psi_quantile_scratch(ref_big, prod_big)\n    mmd2 = rbf_mmd2_unbiased(ref_big[:250, None], prod_big[:250, None])\n    psi_band = \"STABIL(<0.10)\" if psi < 0.10 else (\"MODERAT(0.10-0.25)\" if psi <= 0.25 else \"DRIFT(>0.25)\")\n    print(f\"  {name:26s} | KS D={ks_stat:.4f} p={ks_p:.1e} | W1={w1:.4f} | PSI={psi:.4f} [{psi_band}] | MMD^2={mmd2:+.4f}\")",
          "expectedOutput": "=== BUKTI MONTE CARLO: PERGESERAN MIKRO Delta_mu = 0.05 (15 Trial) ===\n  N=   500 | KS False-Alert(p<0.01)=  6.7% | Med p=1.50e-01 (SciPy=1.50e-01) | Mean W1=0.1018 (diff=0.0e+00) | Mean PSI=0.0405\n  N=  5000 | KS False-Alert(p<0.01)= 46.7% | Med p=1.64e-02 (SciPy=1.64e-02) | Mean W1=0.0546 (diff=1.4e-17) | Mean PSI=0.0063\n  N= 50000 | KS False-Alert(p<0.01)=100.0% | Med p=7.37e-11 (SciPy=1.08e-12) | Mean W1=0.0513 (diff=1.4e-17) | Mean PSI=0.0029\n\n=== PERBANDINGAN METRIK PADA N=50.000 (SUBSAMPLE m=250 UNTUK MMD^2) ===\n  Mikro (mu+0.05, sd=1.0)    | KS D=0.0185 p=7.4e-08 | W1=0.0426 | PSI=0.0018 [STABIL(<0.10)] | MMD^2=-0.0011\n  Moderat (mu+0.40, sd=1.1)  | KS D=0.1558 p=0.0e+00 | W1=0.3988 | PSI=0.1438 [MODERAT(0.10-0.25)] | MMD^2=+0.0289\n  Berat (mu+0.90, sd=1.5)    | KS D=0.3194 p=0.0e+00 | W1=0.9230 | PSI=0.6098 [DRIFT(>0.25)] | MMD^2=+0.1460",
          "actualOutput": "=== BUKTI MONTE CARLO: PERGESERAN MIKRO Delta_mu = 0.05 (15 Trial) ===\n  N=   500 | KS False-Alert(p<0.01)=  6.7% | Med p=1.50e-01 (SciPy=1.50e-01) | Mean W1=0.1018 (diff=0.0e+00) | Mean PSI=0.0405\n  N=  5000 | KS False-Alert(p<0.01)= 46.7% | Med p=1.64e-02 (SciPy=1.64e-02) | Mean W1=0.0546 (diff=1.4e-17) | Mean PSI=0.0063\n  N= 50000 | KS False-Alert(p<0.01)=100.0% | Med p=7.37e-11 (SciPy=1.08e-12) | Mean W1=0.0513 (diff=1.4e-17) | Mean PSI=0.0029\n\n=== PERBANDINGAN METRIK PADA N=50.000 (SUBSAMPLE m=250 UNTUK MMD^2) ===\n  Mikro (mu+0.05, sd=1.0)    | KS D=0.0185 p=7.4e-08 | W1=0.0426 | PSI=0.0018 [STABIL(<0.10)] | MMD^2=-0.0011\n  Moderat (mu+0.40, sd=1.1)  | KS D=0.1558 p=0.0e+00 | W1=0.3988 | PSI=0.1438 [MODERAT(0.10-0.25)] | MMD^2=+0.0289\n  Berat (mu+0.90, sd=1.5)    | KS D=0.3194 p=0.0e+00 | W1=0.9230 | PSI=0.6098 [DRIFT(>0.25)] | MMD^2=+0.1460",
