          "filename": "36_1_multivariate_mmd_domain_classifier.py",
          "code": "import numpy as np\nfrom scipy.stats import wasserstein_distance\nfrom sklearn.ensemble import HistGradientBoostingClassifier\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.metrics import brier_score_loss, roc_auc_score\nfrom sklearn.model_selection import StratifiedKFold, cross_val_predict\nfrom sklearn.pipeline import make_pipeline\nfrom sklearn.preprocessing import PolynomialFeatures, StandardScaler\n\nn = 1200\n\ndef sample_bivariate(n_rows: int, rho: float, shift_noise: float = 0.0, shift_signal: float = 0.0, seed: int = 0):\n    r = np.random.default_rng(seed)\n    z1 = r.normal(0.0, 1.0, size=n_rows)\n    z2 = r.normal(0.0, 1.0, size=n_rows)\n    x0 = z1 + shift_signal\n    x1 = rho * z1 + np.sqrt(1.0 - rho ** 2) * z2\n    x2_noise = r.normal(shift_noise, 1.0, size=n_rows)  # fitur noise tak terpakai target sejati\n    X = np.column_stack([x0, x1, x2_noise])\n    # Target peka terhadap penalti interaksi (x0 - x1)^2 yang kecil saat rho=+0.85, meledak saat rho=-0.85\n    logits = 1.4 * x0 + 1.2 * x1 - 1.5 * ((x0 - x1) ** 2) + 0.4\n    p = 1.0 / (1.0 + np.exp(-np.clip(logits, -20.0, 20.0)))\n    y = r.binomial(1, p)\n    return X, y\n\ndef rbf_mmd2_perm(X: np.ndarray, Y: np.ndarray, n_perm: int = 80, seed: int = 42) -> tuple[float, float]:\n    Z = np.vstack([X, Y])\n    sq = np.sum((Z[:, None, :] - Z[None, :, :]) ** 2, axis=2)\n    med = float(np.median(sq[np.triu_indices(len(Z), k=1)]))\n    K = np.exp(-sq / (2.0 * max(med, 1e-8)))\n    n_x, n_y = len(X), len(Y)\n\n    def stat(idx_x, idx_y):\n        Kxx = K[np.ix_(idx_x, idx_x)]\n        Kyy = K[np.ix_(idx_y, idx_y)]\n        Kxy = K[np.ix_(idx_x, idx_y)]\n        return float(\n            (Kxx.sum() - np.trace(Kxx)) / (n_x * (n_x - 1))\n            + (Kyy.sum() - np.trace(Kyy)) / (n_y * (n_y - 1))\n            - 2.0 * Kxy.mean()\n        )\n\n    obs = stat(np.arange(n_x), np.arange(n_x, n_x + n_y))\n    r = np.random.default_rng(seed)\n    ge = sum(1 for _ in range(n_perm) if stat((perm := r.permutation(n_x + n_y))[:n_x], perm[n_x:]) >= obs)\n    return obs, (ge + 1.0) / (n_perm + 1.0)\n\ndef domain_classifier_auc(X_ref: np.ndarray, X_prod: np.ndarray) -> float:\n    X_all = np.vstack([X_ref, X_prod])\n    y_dom = np.r_[np.zeros(len(X_ref), dtype=int), np.ones(len(X_prod), dtype=int)]\n    cv = StratifiedKFold(n_splits=4, shuffle=True, random_state=42)\n    clf = make_pipeline(StandardScaler(), PolynomialFeatures(2, include_bias=False), LogisticRegression(max_iter=300))\n    oof = cross_val_predict(clf, X_all, y_dom, cv=cv, method=\"predict_proba\")[:, 1]\n    return float(roc_auc_score(y_dom, oof))\n\nX_ref, y_ref = sample_bivariate(n, rho=0.85, seed=42)\nmodel = HistGradientBoostingClassifier(max_depth=4, max_iter=55, random_state=42).fit(X_ref, y_ref)\np_ref = model.predict_proba(X_ref)[:, 1]\nX_val_clean, y_val_clean = sample_bivariate(n, rho=0.85, seed=100)\np_clean = model.predict_proba(X_val_clean)[:, 1]\nauc_base = roc_auc_score(y_val_clean, p_clean)\nbrier_base = brier_score_loss(y_val_clean, p_clean)\n\nscenarios = [\n    (\"1. Benign Noise Shift (X2 +1.2)\", *sample_bivariate(n, rho=0.85, shift_noise=1.2, seed=101)),\n    (\"2. Signal Shift (X0 +0.85)\", *sample_bivariate(n, rho=0.85, shift_signal=0.85, seed=102)),\n    (\"3. Corr Flip (rho: +0.85 -> -0.85)\", *sample_bivariate(n, rho=-0.85, seed=103)),\n]\n\nprint(f\"Baseline Holdout: ROC-AUC = {auc_base:.4f} | Brier = {brier_base:.4f}\")\nfor title, X_p, y_p in scenarios:\n    p_prod = model.predict_proba(X_p)[:, 1]\n    auc_now = roc_auc_score(y_p, p_prod)\n    brier_now = brier_score_loss(y_p, p_prod)\n    w1_x0 = wasserstein_distance(X_ref[:, 0], X_p[:, 0])\n    w1_x1 = wasserstein_distance(X_ref[:, 1], X_p[:, 1])\n    w1_x2 = wasserstein_distance(X_ref[:, 2], X_p[:, 2])\n    w1_score = wasserstein_distance(p_ref, p_prod)\n    mmd2, mmd_p = rbf_mmd2_perm(X_ref[:250, :2], X_p[:250, :2], n_perm=80, seed=42)\n    dom_auc = domain_classifier_auc(X_ref[:, :2], X_p[:, :2])\n    print(f\"\\n[{title}]\")\n    print(f\"  Univariat W1 (X0, X1, X2) = ({w1_x0:.3f}, {w1_x1:.3f}, {w1_x2:.3f}) | Score Shift W1(p) = {w1_score:.4f}\")\n    print(f\"  Multivariat (X0,X1) MMD^2 = {mmd2:.4f} (perm p={mmd_p:.4f}) | Domain Clf AUC = {dom_auc:.4f}\")\n    print(f\"  Dampak Aktual Model       = AUC {auc_now:.4f} (Delta={auc_now - auc_base:+.4f}) | Brier {brier_now:.4f} (Delta={brier_now - brier_base:+.4f})\")",
          "expectedOutput": "Baseline Holdout: ROC-AUC = 0.8962 | Brier = 0.1304\n\n[1. Benign Noise Shift (X2 +1.2)]\n  Univariat W1 (X0, X1, X2) = (0.067, 0.041, 1.160) | Score Shift W1(p) = 0.0349\n  Multivariat (X0,X1) MMD^2 = 0.0003 (perm p=0.4444) | Domain Clf AUC = 0.4976\n  Dampak Aktual Model       = AUC 0.8956 (Delta=-0.0006) | Brier 0.1315 (Delta=+0.0011)\n\n[2. Signal Shift (X0 +0.85)]\n  Univariat W1 (X0, X1, X2) = (0.805, 0.033, 0.085) | Score Shift W1(p) = 0.0676\n  Multivariat (X0,X1) MMD^2 = 0.1067 (perm p=0.0123) | Domain Clf AUC = 0.8526\n  Dampak Aktual Model       = AUC 0.8918 (Delta=-0.0044) | Brier 0.1355 (Delta=+0.0051)\n\n[3. Corr Flip (rho: +0.85 -> -0.85)]\n  Univariat W1 (X0, X1, X2) = (0.062, 0.034, 0.045) | Score Shift W1(p) = 0.2424\n  Multivariat (X0,X1) MMD^2 = 0.0894 (perm p=0.0123) | Domain Clf AUC = 0.9253\n  Dampak Aktual Model       = AUC 0.8646 (Delta=-0.0316) | Brier 0.1217 (Delta=-0.0087)",
          "actualOutput": "Baseline Holdout: ROC-AUC = 0.8962 | Brier = 0.1304\n\n[1. Benign Noise Shift (X2 +1.2)]\n  Univariat W1 (X0, X1, X2) = (0.067, 0.041, 1.160) | Score Shift W1(p) = 0.0349\n  Multivariat (X0,X1) MMD^2 = 0.0003 (perm p=0.4444) | Domain Clf AUC = 0.4976\n  Dampak Aktual Model       = AUC 0.8956 (Delta=-0.0006) | Brier 0.1315 (Delta=+0.0011)\n\n[2. Signal Shift (X0 +0.85)]\n  Univariat W1 (X0, X1, X2) = (0.805, 0.033, 0.085) | Score Shift W1(p) = 0.0676\n  Multivariat (X0,X1) MMD^2 = 0.1067 (perm p=0.0123) | Domain Clf AUC = 0.8526\n  Dampak Aktual Model       = AUC 0.8918 (Delta=-0.0044) | Brier 0.1355 (Delta=+0.0051)\n\n[3. Corr Flip (rho: +0.85 -> -0.85)]\n  Univariat W1 (X0, X1, X2) = (0.062, 0.034, 0.045) | Score Shift W1(p) = 0.2424\n  Multivariat (X0,X1) MMD^2 = 0.0894 (perm p=0.0123) | Domain Clf AUC = 0.9253\n  Dampak Aktual Model       = AUC 0.8646 (Delta=-0.0316) | Brier 0.1217 (Delta=-0.0087)",
          "explanation": "Menguji 3 skenario pada HistGradientBoostingClassifier: saat korelasi (X0, X1) berbalik +0.85 -> -0.85, W1 univariat tetap dekat nol (0.062, 0.034) meski AUC turun -0.0316, sedangkan RBF MMD^2 (p=0.0123), Domain Classifier AUC (0.9253), dan Score Shift W1(p)=0.2424 langsung menyala.",
