          "id": "code-ml-36-2-ch36_2_diag",
          "title": "Production Audit: Selective Labeling Feedback Loop (5 Generasi -> Bias -0.1004 vs IPS +0.0037) & Kish ESS vs Half-Life",
          "language": "python",
          "filename": "36_2_feedback_loop_ips_and_kish_ess_audit.py",
          "code": "import numpy as np\nfrom sklearn.ensemble import GradientBoostingClassifier\nfrom sklearn.metrics import brier_score_loss, roc_auc_score\n\n# Audit 1: Selective Labeling Feedback Loop (Model Collapse) vs 8% Exploration + IPS Debiasing\ndef gen_credit(n_rows: int, seed: int):\n    r = np.random.default_rng(seed)\n    X = r.normal(0.0, 1.0, size=(n_rows, 3))\n    z = -1.2 + 2.2 * X[:, 0] - 0.8 * X[:, 1] + 0.5 * X[:, 2] + 1.8 * (X[:, 0] > 0.5).astype(float)\n    p_def = 1.0 / (1.0 + np.exp(-np.clip(z, -20.0, 20.0)))\n    return X, r.binomial(1, p_def)\n\nX_test_pop, y_test_pop = gen_credit(3000, seed=999)\nX_init, y_init = gen_credit(600, seed=1)\n\ndef run_generations(explore_rate: float, use_ips: bool):\n    clf = GradientBoostingClassifier(n_estimators=30, max_depth=3, random_state=42).fit(X_init, y_init)\n    X_hist, y_hist, w_hist = [], [], []\n    for gen in range(1, 6):\n        Xg, yg = gen_credit(1500, seed=100 + gen)\n        p_hat = clf.predict_proba(Xg)[:, 1]\n        approve_pol = p_hat < 0.30\n        explore_flg = np.random.default_rng(500 + gen).random(len(Xg)) < explore_rate\n        obs = approve_pol | explore_flg\n        prop = np.where(approve_pol, 1.0, max(explore_rate, 1e-6))\n        w_g = (1.0 / prop[obs]) if use_ips else np.ones(int(np.sum(obs)))\n        X_hist.append(Xg[obs])\n        y_hist.append(yg[obs])\n        w_hist.append(w_g)\n        clf = GradientBoostingClassifier(n_estimators=30, max_depth=3, random_state=42).fit(\n            np.vstack(X_hist[-2:]), np.concatenate(y_hist[-2:]), sample_weight=np.concatenate(w_hist[-2:])\n        )\n    p_eval = clf.predict_proba(X_test_pop)[:, 1]\n    hi_risk = X_test_pop[:, 0] > 0.6\n    return (\n        float(roc_auc_score(y_test_pop, p_eval)),\n        float(brier_score_loss(y_test_pop, p_eval)),\n        float(np.mean(p_eval[hi_risk]) - np.mean(y_test_pop[hi_risk])),\n    )\n\nprint(\"=== AUDIT 1: SELECTIVE LABELING FEEDBACK LOOP (5 GENERASI RETRAINING) ===\")\nfor name, eps, ips in [\n    (\"Greedy 0% Exploration (Collapse)\", 0.0, False),\n    (\"8% Exploration Tanpa IPS\", 0.08, False),\n    (\"8% Exploration + IPS Debiasing\", 0.08, True),\n]:\n    auc5, brier5, rej_bias = run_generations(eps, ips)\n    print(f\"  {name:32s} | Gen-5 AUC={auc5:.4f} | Brier={brier5:.4f} | High-Risk Calib Bias={rej_bias:+.4f}\")\n\n# Audit 2: Kish Effective Sample Size (ESS) untuk Exponential Decay Weights (180 hari, 100 baris/hari)\nprint(\"\\n=== AUDIT 2: KISH EFFECTIVE SAMPLE SIZE (ESS) VS HALF-LIFE DECAY (N_raw = 18.000) ===\")\nages_days = np.repeat(np.arange(180, dtype=float), 100)\nfor H in [7.0, 14.0, 30.0, 60.0, 180.0]:\n    w = 2.0 ** (-ages_days / H)\n    ess = float((np.sum(w) ** 2) / np.sum(w ** 2))\n    pct_last_30d = 100.0 * float(np.sum(w[ages_days < 30]) / np.sum(w))\n    print(f\"  Half-life H={H:5.1f} hari | Kish ESS={ess:7.1f} ({100*ess/len(ages_days):5.1f}% N_raw) | Bobot 30-hari terakhir={pct_last_30d:5.1f}%\")",
          "expectedOutput": "=== AUDIT 1: SELECTIVE LABELING FEEDBACK LOOP (5 GENERASI RETRAINING) ===\n  Greedy 0% Exploration (Collapse) | Gen-5 AUC=0.9304 | Brier=0.1055 | High-Risk Calib Bias=-0.1004\n  8% Exploration Tanpa IPS         | Gen-5 AUC=0.9305 | Brier=0.1034 | High-Risk Calib Bias=-0.0380\n  8% Exploration + IPS Debiasing   | Gen-5 AUC=0.9277 | Brier=0.1038 | High-Risk Calib Bias=+0.0037\n\n=== AUDIT 2: KISH EFFECTIVE SAMPLE SIZE (ESS) VS HALF-LIFE DECAY (N_raw = 18.000) ===\n  Half-life H=  7.0 hari | Kish ESS= 2021.4 ( 11.2% N_raw) | Bobot 30-hari terakhir= 94.9%\n  Half-life H= 14.0 hari | Kish ESS= 4039.3 ( 22.4% N_raw) | Bobot 30-hari terakhir= 77.4%\n  Half-life H= 30.0 hari | Kish ESS= 8390.2 ( 46.6% N_raw) | Bobot 30-hari terakhir= 50.8%\n  Half-life H= 60.0 hari | Kish ESS=13465.3 ( 74.8% N_raw) | Bobot 30-hari terakhir= 33.5%\n  Half-life H=180.0 hari | Kish ESS=17312.4 ( 96.2% N_raw) | Bobot 30-hari terakhir= 21.8%",
          "actualOutput": "=== AUDIT 1: SELECTIVE LABELING FEEDBACK LOOP (5 GENERASI RETRAINING) ===\n  Greedy 0% Exploration (Collapse) | Gen-5 AUC=0.9304 | Brier=0.1055 | High-Risk Calib Bias=-0.1004\n  8% Exploration Tanpa IPS         | Gen-5 AUC=0.9305 | Brier=0.1034 | High-Risk Calib Bias=-0.0380\n  8% Exploration + IPS Debiasing   | Gen-5 AUC=0.9277 | Brier=0.1038 | High-Risk Calib Bias=+0.0037\n\n=== AUDIT 2: KISH EFFECTIVE SAMPLE SIZE (ESS) VS HALF-LIFE DECAY (N_raw = 18.000) ===\n  Half-life H=  7.0 hari | Kish ESS= 2021.4 ( 11.2% N_raw) | Bobot 30-hari terakhir= 94.9%\n  Half-life H= 14.0 hari | Kish ESS= 4039.3 ( 22.4% N_raw) | Bobot 30-hari terakhir= 77.4%\n  Half-life H= 30.0 hari | Kish ESS= 8390.2 ( 46.6% N_raw) | Bobot 30-hari terakhir= 50.8%\n  Half-life H= 60.0 hari | Kish ESS=13465.3 ( 74.8% N_raw) | Bobot 30-hari terakhir= 33.5%\n  Half-life H=180.0 hari | Kish ESS=17312.4 ( 96.2% N_raw) | Bobot 30-hari terakhir= 21.8%",
