          "code": "import hashlib\nimport json\n\nPROHIBITED_DOMAINS = {\"public_social_scoring\", \"workplace_emotion_recognition\", \"subliminal_manipulation\"}\nHIGH_RISK_ANNEX_III = {\"credit_scoring\", \"hr_recruitment\", \"medical_triage\", \"law_enforcement\", \"critical_infra\"}\nLIMITED_RISK_DOMAINS = {\"customer_chatbot\", \"synthetic_media_generation\"}\n\ndef classify_eu_ai_act(use_case: dict) -> dict:\n    dom = use_case[\"domain\"]\n    if dom in PROHIBITED_DOMAINS:\n        return {\"tier\": \"PROHIBITED (Art. 5)\", \"deploy_allowed\": False, \"max_fine\": \"EUR 35M or 7% global turnover\", \"nist_gate\": \"BLOCK_IMMEDIATE\"}\n    if dom in HIGH_RISK_ANNEX_III:\n        return {\"tier\": \"HIGH-RISK (Annex III, Art. 6)\", \"deploy_allowed\": True, \"max_fine\": \"EUR 15M or 3% global turnover\", \"nist_gate\": \"GOVERN+MAP+MEASURE+MANAGE\"}\n    if dom in LIMITED_RISK_DOMAINS:\n        return {\"tier\": \"LIMITED RISK (Art. 50)\", \"deploy_allowed\": True, \"max_fine\": \"EUR 15M or 3% global turnover\", \"nist_gate\": \"TRANSPARENCY_DISCLOSURE\"}\n    return {\"tier\": \"MINIMAL RISK\", \"deploy_allowed\": True, \"max_fine\": \"Voluntary Code of Conduct\", \"nist_gate\": \"STANDARD_QA\"}\n\ndef canonical_hash(prev_hash: str, payload: dict) -> str:\n    blob = json.dumps({\"prev\": prev_hash, \"payload\": payload}, sort_keys=True, separators=(\",\", \":\")).encode(\"utf-8\")\n    return hashlib.sha256(blob).hexdigest()\n\nclass ImmutableAuditLedger:\n    def __init__(self):\n        self.chain: list[dict] = []\n\n    def append(self, event_type: str, data: dict) -> str:\n        prev = self.chain[-1][\"hash\"] if self.chain else \"0\" * 64\n        entry = {\"seq\": len(self.chain), \"event\": event_type, \"data\": data, \"prev_hash\": prev}\n        entry[\"hash\"] = canonical_hash(prev, {\"seq\": entry[\"seq\"], \"event\": event_type, \"data\": data})\n        self.chain.append(entry)\n        return entry[\"hash\"]\n\n    def verify(self) -> tuple[bool, int | None]:\n        prev = \"0\" * 64\n        for idx, blk in enumerate(self.chain):\n            if blk[\"prev_hash\"] != prev:\n                return False, idx\n            expected = canonical_hash(prev, {\"seq\": blk[\"seq\"], \"event\": blk[\"event\"], \"data\": blk[\"data\"]})\n            if blk[\"hash\"] != expected:\n                return False, idx\n            prev = blk[\"hash\"]\n        return True, None\n\nprint(\"=== 1. KLASIFIKASI RISIKO EU AI ACT (REG. 2024/1689) ===\")\nfor uc in [\n    {\"name\": \"Credit Scoring Ritel\", \"domain\": \"credit_scoring\"},\n    {\"name\": \"Detektor Emosi Karyawan\", \"domain\": \"workplace_emotion_recognition\"},\n    {\"name\": \"Chatbot CS Transparan\", \"domain\": \"customer_chatbot\"},\n    {\"name\": \"Filter Spam Email\", \"domain\": \"spam_filter\"},\n]:\n    res = classify_eu_ai_act(uc)\n    print(f\"  {uc['name']:24s} -> {res['tier']:30s} | Allowed={str(res['deploy_allowed']):5s} | Gate={res['nist_gate']}\")\n\nprint(\"\\n=== 2. IMMUTABLE SHA-256 AUDIT LEDGER & TAMPER DETECTION ===\")\nledger = ImmutableAuditLedger()\nledger.append(\"DATA_SNAPSHOT\", {\"dataset_id\": \"credit_2026_q1\", \"rows\": 120000, \"sha256\": \"a19f0e\"})\nledger.append(\"MODEL_TRAINED\", {\"model_id\": \"hgb_credit_v4.2\", \"auc\": 0.874, \"ece\": 0.019})\nledger.append(\"FAIRNESS_AUDIT\", {\"min_subgroup_dir\": 0.862, \"max_eod_gap\": 0.031, \"status\": \"PASS\"})\nledger.append(\"CANARY_PROMOTE\", {\"approver\": \"risk_committee_signoff\", \"traffic_pct\": 100})\n\nok_clean, bad_idx = ledger.verify()\nprint(f\"  Verifikasi Rantai Asli (4 blok) : valid={ok_clean} | tip_hash={ledger.chain[-1]['hash'][:16]}...\")\n\nledger.chain[2][\"data\"][\"min_subgroup_dir\"] = 0.910\nok_tampered, bad_idx = ledger.verify()\nprint(f\"  Pasca Manipulasi Blok #2        : valid={ok_tampered} | TAMPER TERDETEKSI DI BLOK #{bad_idx} ({ledger.chain[bad_idx]['event']})\")",
          "expectedOutput": "=== 1. KLASIFIKASI RISIKO EU AI ACT (REG. 2024/1689) ===\n  Credit Scoring Ritel     -> HIGH-RISK (Annex III, Art. 6)  | Allowed=True  | Gate=GOVERN+MAP+MEASURE+MANAGE\n  Detektor Emosi Karyawan  -> PROHIBITED (Art. 5)            | Allowed=False | Gate=BLOCK_IMMEDIATE\n  Chatbot CS Transparan    -> LIMITED RISK (Art. 50)         | Allowed=True  | Gate=TRANSPARENCY_DISCLOSURE\n  Filter Spam Email        -> MINIMAL RISK                   | Allowed=True  | Gate=STANDARD_QA\n\n=== 2. IMMUTABLE SHA-256 AUDIT LEDGER & TAMPER DETECTION ===\n  Verifikasi Rantai Asli (4 blok) : valid=True | tip_hash=491be6d992c158ef...\n  Pasca Manipulasi Blok #2        : valid=False | TAMPER TERDETEKSI DI BLOK #2 (FAIRNESS_AUDIT)",
