          "code": "import hashlib\nimport json\nimport numpy as np\nfrom sklearn.calibration import CalibratedClassifierCV\nfrom sklearn.ensemble import HistGradientBoostingClassifier\nfrom sklearn.frozen import FrozenEstimator\nfrom sklearn.metrics import average_precision_score, brier_score_loss, roc_auc_score\nfrom sklearn.model_selection import train_test_split\n\ndef wilson_ci(k: int, n: int, z: float = 1.96) -> tuple[float, float]:\n    if n == 0:\n        return (0.0, 1.0)\n    p = k / n\n    denom = 1.0 + z * z / n\n    center = (p + z * z / (2.0 * n)) / denom\n    half = (z * np.sqrt((p * (1.0 - p) + z * z / (4.0 * n)) / n)) / denom\n    return (round(float(max(0.0, center - half)), 4), round(float(min(1.0, center + half)), 4))\n\ndef quantile_ece(y_true: np.ndarray, y_prob: np.ndarray, n_bins: int = 10) -> float:\n    edges = np.quantile(y_prob, np.linspace(0.0, 1.0, n_bins + 1))\n    edges[0], edges[-1] = 0.0, 1.0\n    ece = 0.0\n    for b in range(n_bins):\n        m = (y_prob >= edges[b]) & (y_prob <= edges[b + 1] if b == n_bins - 1 else y_prob < edges[b + 1])\n        if np.any(m):\n            ece += (np.sum(m) / len(y_true)) * abs(float(np.mean(y_true[m])) - float(np.mean(y_prob[m])))\n    return float(ece)\n\nrng = np.random.default_rng(42)\nn = 2000\ngender = rng.binomial(1, 0.45, size=n)\nage45 = rng.binomial(1, 0.40, size=n)\nincome, dti, history, savings = [rng.normal(0.0, 1.0, size=n) for _ in range(4)]\nX = np.column_stack([income, dti, history, savings])\nlogits = 0.35 + 1.35 * income - 1.55 * dti + 1.05 * history + 0.65 * savings - 0.10 * gender - 0.08 * age45\ny = rng.binomial(1, 1.0 / (1.0 + np.exp(-logits)))\nmeta = np.column_stack([gender, age45])\n\nX_tr, X_tmp, y_tr, y_tmp, m_tr, m_tmp = train_test_split(X, y, meta, test_size=0.40, stratify=y, random_state=42)\nX_cal, X_te, y_cal, y_te, m_cal, m_te = train_test_split(X_tmp, y_tmp, m_tmp, test_size=0.50, stratify=y_tmp, random_state=42)\n\nbase = HistGradientBoostingClassifier(max_depth=4, max_iter=45, random_state=42).fit(X_tr, y_tr)\ncal = CalibratedClassifierCV(FrozenEstimator(base), method=\"sigmoid\").fit(X_cal, y_cal)\nprobs = cal.predict_proba(X_te)[:, 1]\npreds = (probs >= 0.50).astype(int)\n\nsubgroups, sel_rates, tprs, fprs = {}, [], [], []\nfor g_val in [0, 1]:\n    for a_val in [0, 1]:\n        key = f\"gender={g_val}_age45={a_val}\"\n        mask = (m_te[:, 0] == g_val) & (m_te[:, 1] == a_val)\n        n_sub = int(np.sum(mask))\n        sel = float(np.mean(preds[mask]))\n        tpr = float(np.mean(preds[mask & (y_te == 1)]))\n        fpr = float(np.mean(preds[mask & (y_te == 0)]))\n        subgroups[key] = {\"n\": n_sub, \"approval_rate\": round(sel, 4), \"ci95\": wilson_ci(int(np.sum(preds[mask])), n_sub), \"tpr\": round(tpr, 4), \"fpr\": round(fpr, 4)}\n        sel_rates.append(sel)\n        tprs.append(tpr)\n        fprs.append(fpr)\n\nmin_dir = float(min(sel_rates) / max(sel_rates))\nmax_eod = float(max(max(tprs) - min(tprs), max(fprs) - min(fprs)))\nglobal_auc = float(roc_auc_score(y_te, probs))\nglobal_ece = quantile_ece(y_te, probs)\nschema_hash = hashlib.sha256(b\"income,dti,history,savings\").hexdigest()[:12]\n\ngate_checks = {\n    \"auc_ge_0.82\": global_auc >= 0.82,\n    \"ece_le_0.04\": global_ece <= 0.04,\n    \"intersectional_dir_ge_0.80\": min_dir >= 0.80,\n    \"intersectional_eod_le_0.10\": max_eod <= 0.10,\n}\nmodel_card = {\n    \"model_id\": \"credit_underwriting_hgb_cal_v2026.1\",\n    \"eu_ai_act_tier\": \"HIGH-RISK (Annex III, 5b - Creditworthiness)\",\n    \"feature_schema_sha256\": schema_hash,\n    \"global_metrics\": {\n        \"roc_auc\": round(global_auc, 4),\n        \"pr_auc\": round(float(average_precision_score(y_te, probs)), 4),\n        \"brier\": round(float(brier_score_loss(y_te, probs)), 4),\n        \"quantile_ece\": round(global_ece, 4),\n    },\n    \"fairness_intersectional\": {\"min_dir\": round(min_dir, 4), \"max_eod_gap\": round(max_eod, 4)},\n    \"release_gate_checks\": gate_checks,\n    \"release_decision\": \"APPROVED\" if all(gate_checks.values()) else \"BLOCKED_FOR_REMEDIATION\",\n}\nprint(\"=== AUTOMATED MODEL CARD (MITCHELL 2019 / NIST MEASURE) ===\")\nprint(json.dumps(model_card, indent=2))\nprint(f\"\\nDisagregasi 4 Subgrup Interseksional (Holdout N={len(y_te)}):\")\nfor k, v in subgroups.items():\n    print(f\"  {k:20s} | n={v['n']:3d} | AppRate={v['approval_rate']:.3f} CI95={v['ci95']} | TPR={v['tpr']:.3f} | FPR={v['fpr']:.3f}\")",
          "expectedOutput": "=== AUTOMATED MODEL CARD (MITCHELL 2019 / NIST MEASURE) ===\n{\n  \"model_id\": \"credit_underwriting_hgb_cal_v2026.1\",\n  \"eu_ai_act_tier\": \"HIGH-RISK (Annex III, 5b - Creditworthiness)\",\n  \"feature_schema_sha256\": \"78d738f91757\",\n  \"global_metrics\": {\n    \"roc_auc\": 0.8711,\n    \"pr_auc\": 0.8726,\n    \"brier\": 0.1437,\n    \"quantile_ece\": 0.0453\n  },\n  \"fairness_intersectional\": {\n    \"min_dir\": 0.8831,\n    \"max_eod_gap\": 0.0615\n  },\n  \"release_gate_checks\": {\n    \"auc_ge_0.82\": true,\n    \"ece_le_0.04\": false,\n    \"intersectional_dir_ge_0.80\": true,\n    \"intersectional_eod_le_0.10\": true\n  },\n  \"release_decision\": \"BLOCKED_FOR_REMEDIATION\"\n}\n\nDisagregasi 4 Subgrup Interseksional (Holdout N=400):\n  gender=0_age45=0     | n=142 | AppRate=0.535 CI95=(0.4533, 0.6152) | TPR=0.805 | FPR=0.215\n  gender=0_age45=1     | n= 71 | AppRate=0.535 CI95=(0.4204, 0.6464) | TPR=0.816 | FPR=0.212\n  gender=1_age45=0     | n=109 | AppRate=0.532 CI95=(0.4389, 0.6231) | TPR=0.807 | FPR=0.231\n  gender=1_age45=1     | n= 78 | AppRate=0.603 CI95=(0.4916, 0.7039) | TPR=0.867 | FPR=0.242",
