          "starterCode": "import hashlib\nimport json\n\ndef verify_audit_chain_and_gate(events: list[dict], subgroup_rates: list[float], ece: float) -> tuple[bool, int, float, bool]:\n    # TODO: verifikasi rantai SHA-256 -> hitung min_dir -> evaluasi release_ok\n    pass\n\ndef _mk(prev, seq, payload):\n    b = json.dumps({\"prev\": prev, \"seq\": seq, \"payload\": payload}, sort_keys=True, separators=(\",\", \":\")).encode(\"utf-8\")\n    return {\"seq\": seq, \"prev_hash\": prev, \"payload\": payload, \"hash\": hashlib.sha256(b).hexdigest()}\n\ne0 = _mk(\"0\" * 64, 0, {\"stage\": \"data_freeze\", \"rows\": 50000})\ne1 = _mk(e0[\"hash\"], 1, {\"stage\": \"audit\", \"auc\": 0.88})\ne2 = _mk(e1[\"hash\"], 2, {\"stage\": \"deploy\", \"env\": \"prod\"})\ne1_tampered = dict(e1, payload={\"stage\": \"audit\", \"auc\": 0.94})\nprint(verify_audit_chain_and_gate([e0, e1_tampered, e2], [0.52, 0.44, 0.46, 0.49], 0.025))",
