          "code": "import numpy as np\nfrom sklearn.calibration import CalibratedClassifierCV\nfrom sklearn.ensemble import HistGradientBoostingClassifier\nfrom sklearn.frozen import FrozenEstimator\nfrom sklearn.metrics import roc_auc_score\nfrom sklearn.model_selection import train_test_split\n\nrng = np.random.default_rng(42)\nn = 2000\nusia = rng.uniform(22.0, 62.0, size=n)\npendapatan = rng.uniform(4.0, 35.0, size=n)\nrasio_utang = rng.uniform(0.05, 0.90, size=n)\ntunggakan = rng.poisson(0.7, size=n).astype(float)\ntabungan = rng.uniform(1.0, 80.0, size=n)\ngroup_audit = rng.binomial(1, 0.45, size=n)\n\nX = np.column_stack([usia, pendapatan, rasio_utang, tunggakan, tabungan])\nlogits = -1.1 + 0.12 * pendapatan - 4.4 * rasio_utang - 0.85 * tunggakan + 0.035 * tabungan\ny = rng.binomial(1, 1.0 / (1.0 + np.exp(-logits)))\n\nX_tr, X_tmp, y_tr, y_tmp, g_tr, g_tmp = train_test_split(X, y, group_audit, test_size=0.40, stratify=y, random_state=42)\nX_cal, X_te, y_cal, y_te, g_cal, g_te = train_test_split(X_tmp, y_tmp, g_tmp, test_size=0.50, stratify=y_tmp, random_state=42)\n\nmono_cst = [0, 1, -1, -1, 1]\nbase_free = HistGradientBoostingClassifier(max_depth=5, max_iter=50, random_state=42).fit(X_tr, y_tr)\nbase_mono = HistGradientBoostingClassifier(max_depth=5, max_iter=50, monotonic_cst=mono_cst, random_state=42).fit(X_tr, y_tr)\ncal_mono = CalibratedClassifierCV(FrozenEstimator(base_mono), method=\"sigmoid\").fit(X_cal, y_cal)\n\nX_pert = X_te.copy()\nX_pert[:, 2] = np.clip(X_pert[:, 2] + 0.15, 0.05, 0.95)\nviol_free = int(np.sum(base_free.predict_proba(X_pert)[:, 1] > base_free.predict_proba(X_te)[:, 1] + 1e-6))\nviol_mono = int(np.sum(cal_mono.predict_proba(X_pert)[:, 1] > cal_mono.predict_proba(X_te)[:, 1] + 1e-6))\n\np_te = cal_mono.predict_proba(X_te)[:, 1]\nauto_app = p_te >= 0.65\nauto_dec = p_te < 0.35\nhuman_rev = ~(auto_app | auto_dec)\nauto_mask = auto_app | auto_dec\nacc_all = float(np.mean((p_te >= 0.50) == y_te))\nacc_auto = float(np.mean((p_te[auto_mask] >= 0.50) == y_te[auto_mask]))\n\nrej_idx = int(np.where((p_te > 0.22) & (p_te < 0.34))[0][0])\nx0 = X_te[rej_idx]\nmad = np.maximum(np.median(np.abs(X_tr - np.median(X_tr, axis=0)), axis=0), 1e-6)\ngrid_u = np.linspace(0.0, 0.55, 23)\ngrid_t = np.linspace(0.0, 45.0, 19)\ncands = np.array([[x0[0], x0[1], max(0.05, x0[2] - du), x0[3], min(95.0, x0[4] + dt)] for du in grid_u for dt in grid_t])\np_cands = cal_mono.predict_proba(cands)[:, 1]\nvalid_cf = cands[p_cands >= 0.68]\ndists = np.sum(np.abs(valid_cf - x0) / mad, axis=1)\nbest_i = int(np.argmin(dists))\nbest_cf, best_dist = valid_cf[best_i], float(dists[best_i])\np_cf = float(cal_mono.predict_proba(best_cf.reshape(1, -1))[0, 1])\n\nrate_g0 = float(np.mean(p_te[g_te == 0] >= 0.50))\nrate_g1 = float(np.mean(p_te[g_te == 1] >= 0.50))\ndir_val = min(rate_g0, rate_g1) / max(rate_g0, rate_g1)\n\nprint(\"=== BLUEPRINT #3: REGULATED CREDIT (MONOTONIC GBDT + REJECT BAND + RECOURSE + AUDIT) ===\")\nprint(f\"  ROC-AUC Holdout          : Unconstrained={roc_auc_score(y_te, base_free.predict_proba(X_te)[:,1]):.4f} | Monotonic+Cal={roc_auc_score(y_te, p_te):.4f}\")\nprint(f\"  Pelanggaran Monotonisitas: Unconstrained={viol_free} kasus (FAIL) | Monotonic GBDT={viol_mono} kasus (100% PASS)\")\nprint(f\"  3-Zona Keputusan         : Auto-Approve={100*auto_app.mean():.1f}% | Human-Review={100*human_rev.mean():.1f}% | Auto-Decline={100*auto_dec.mean():.1f}%\")\nprint(f\"  Akurasi Keputusan        : 100% Otomatis={100*acc_all:.1f}% -> Zona Otomatis (Abstention)={100*acc_auto:.1f}%\")\nprint(f\"  Actionable Recourse (#{rej_idx}): p0={p_te[rej_idx]:.3f} -> p_cf={p_cf:.3f} (usia terkunci={best_cf[0]:.1f}=={x0[0]:.1f})\")\nprint(f\"    Saran Minimal (L1-MAD={best_dist:.2f}): rasio_utang {x0[2]:.2f}->{best_cf[2]:.2f}, tabungan {x0[4]:.1f}->{best_cf[4]:.1f}\")\nprint(f\"  EU AI Act Annex III Audit: DIR={dir_val:.4f} ({'PASS >=0.80' if dir_val >= 0.80 else 'FAIL'}) | Human Oversight Gate=ACTIVE\")",
